import sys

def longestKSubstr(S: str, K: int) -> int:
    n = len(S)
    if K > 26 or K > n:
        total_unique = len(set(S))
        if total_unique < K:
            return -1

    left = 0
    freq = {}
    unique_count = 0
    max_len = -1

    for right in range(n):
        char = S[right]
        if char not in freq:
            freq[char] = 0
        if freq[char] == 0:
            unique_count += 1
        freq[char] += 1

        while unique_count > K:
            left_char = S[left]
            freq[left_char] -= 1
            if freq[left_char] == 0:
                unique_count -= 1
            left += 1

        if unique_count == K:
            current_len = right - left + 1
            if current_len > max_len:
                max_len = current_len

    return max_len

def main():
    try:
        line1 = sys.stdin.readline().strip()
        line2 = sys.stdin.readline().strip()
        if not line1 or not line2:
            return
        S = line1
        K = int(line2)
        result = longestKSubstr(S, K)
        print(result)
    except (IOError, ValueError):
        pass

if __name__ == "__main__":
    main()
